<?php
$mine=current_user()['role']==='cliente'?client_for_user():null;$clients=current_user()['role']!=='cliente'?db()->query('SELECT id,name FROM clients WHERE active=1 ORDER BY name')->fetchAll():[];
$sql='SELECT a.*,c.name client_name,u.name staff_name FROM attendance a JOIN clients c ON c.id=a.client_id LEFT JOIN users u ON u.id=a.recorded_by';$args=[];
if(current_user()['role']==='cliente'){if(!$mine){$sql.=' WHERE a.client_id=0';}else{$sql.=' WHERE a.client_id=?';$args[]=$mine['id'];}}
$sql.=' ORDER BY a.checkin_at DESC LIMIT 100';$s=db()->prepare($sql);$s->execute($args);$rows=$s->fetchAll();
?>
<div class="grid cols"><section class="card panel"><div class="panel-head"><h2>Registrar asistencia</h2></div><p class="muted">Registra el ingreso de un cliente con membresía vigente.</p><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="attendance_create"><?php if(current_user()['role']!=='cliente'): ?><label>Cliente<select name="client_id" required><option value="">Seleccionar</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach; ?></select></label><?php else: ?><p>Cliente: <b><?=h($mine['name']??'Perfil no vinculado')?></b></p><?php endif; ?><div class="form-actions"><button class="btn primary">✓ Registrar ingreso</button></div></form></section><section class="membership-highlight"><span class="eyebrow">CONTROL DE ACCESO</span><h2>Asistencia digital</h2><p>El ingreso se permite cuando existe una membresía vigente. Los registros ayudan a comprender la frecuencia de visita.</p></section></div>
<section class="card panel"><div class="panel-head"><h2><?=is_admin()?'Últimos ingresos':'Mi historial de asistencia'?></h2><input class="search" data-search="#attendance-table" placeholder="Buscar cliente…"></div><div class="table-wrap"><table id="attendance-table"><thead><tr><th>CLIENTE</th><th>FECHA Y HORA</th><th>REGISTRADO POR</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['client_name'])?></td><td><?=date('d/m/Y H:i',strtotime($r['checkin_at']))?></td><td><?=h($r['staff_name']??'—')?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="3" class="empty">Sin registros de asistencia.</td></tr><?php endif; ?></tbody></table></div></section>
